#include <algorithm>
#include <functional>
#include <iostream>
#include <limits>
#include <numeric>
#include <optional>
#include <queue>
#include <sstream>
#include <string>
#include <tuple>
#include <unordered_map>
#include <utility>
#include <vector>

class RoadMap
{
public:
    int place(const std::string& name)
    {
        auto it = ids_.find(name);
        if (it != ids_.end()) return it->second;
        int id = static_cast<int>(names_.size());
        ids_[name] = id;
        names_.push_back(name);
        adj_.emplace_back();
        return id;
    }

    std::optional<int> find(const std::string& name) const
    {
        auto it = ids_.find(name);
        if (it == ids_.end()) return std::nullopt;
        return it->second;
    }

    const std::string& name(int id) const { return names_[id]; }
    int count() const { return static_cast<int>(names_.size()); }
    const std::vector<std::string>& names() const { return names_; }

    bool setRoad(int a, int b, long long minutes)       // true if new
    {
        for (auto& [v, m] : adj_[a])
            if (v == b)
            {
                m = minutes;
                for (auto& [u, m2] : adj_[b])
                    if (u == a) m2 = minutes;
                return false;
            }
        adj_[a].push_back({ b, minutes });
        adj_[b].push_back({ a, minutes });
        return true;
    }

    bool closeRoad(int a, int b)
    {
        auto drop = [](std::vector<std::pair<int, long long>>& list, int other) {
            auto it = std::find_if(list.begin(), list.end(), [&](const auto& e) { return e.first == other; });
            if (it == list.end()) return false;
            list.erase(it);
            return true;
        };
        if (!drop(adj_[a], b)) return false;
        drop(adj_[b], a);
        return true;
    }

    struct Label
    {
        long long minutes;
        int roads;
        bool operator<(const Label& o) const { return std::tie(minutes, roads) < std::tie(o.minutes, o.roads); }
        bool operator>(const Label& o) const { return o < *this; }
    };

    // Fastest (then fewest roads) labels from `from`; parent links for rebuilding routes.
    std::vector<std::optional<Label>> fastest(int from, std::vector<int>& parent) const
    {
        std::vector<std::optional<Label>> best(adj_.size());
        parent.assign(adj_.size(), -1);
        using Item = std::pair<Label, int>;
        auto later = [](const Item& x, const Item& y) { return x.first > y.first; };
        std::priority_queue<Item, std::vector<Item>, decltype(later)> pq(later);
        best[from] = Label{ 0, 0 };
        pq.push({ Label{ 0, 0 }, from });
        while (!pq.empty())
        {
            auto [label, u] = pq.top();
            pq.pop();
            if (*best[u] < label) continue;
            for (auto [v, m] : adj_[u])
            {
                Label next{ label.minutes + m, label.roads + 1 };
                if (!best[v] || next < *best[v])
                {
                    best[v] = next;
                    parent[v] = u;
                    pq.push({ next, v });
                }
            }
        }
        return best;
    }

    std::tuple<long long, int, int> network() const        // total minutes, roads used, parts
    {
        std::vector<std::tuple<long long, int, int>> edges;
        for (int u = 0; u < count(); ++u)
            for (auto [v, m] : adj_[u])
                if (u < v) edges.push_back({ m, u, v });
        std::sort(edges.begin(), edges.end());
        std::vector<int> parent(count());
        std::iota(parent.begin(), parent.end(), 0);
        std::function<int(int)> root = [&](int x) { while (parent[x] != x) x = parent[x] = parent[parent[x]]; return x; };
        long long total = 0;
        int used = 0;
        for (auto [m, u, v] : edges)
        {
            int a = root(u), b = root(v);
            if (a == b) continue;
            parent[b] = a;
            total += m;
            ++used;
        }
        return { total, used, count() - used };
    }

private:
    std::unordered_map<std::string, int> ids_;
    std::vector<std::string> names_;
    std::vector<std::vector<std::pair<int, long long>>> adj_;
};

static std::optional<long long> wholeNumber(const std::string& s, long long low, long long high)
{
    if (s.empty() || s.size() > 10) return std::nullopt;
    for (char c : s)
        if (c < '0' || c > '9') return std::nullopt;
    long long n = std::stoll(s);
    if (n < low || n > high) return std::nullopt;
    return n;
}

static std::string plural(long long n, const char* one, const char* many) { return std::to_string(n) + " " + (n == 1 ? one : many); }

int main()
{
    RoadMap map;
    const std::vector<std::pair<std::string, std::string>> usage{
        { "road", "road <a> <b> <minutes>" }, { "close", "close <a> <b>" }, { "route", "route <a> <b>" },
        { "reach", "reach <a> <minutes>" }, { "far", "far <a>" }, { "network", "network" }, { "places", "places" } };

    std::string line;
    while (std::getline(std::cin, line))
    {
        std::istringstream in(line);
        std::vector<std::string> w;
        for (std::string word; in >> word;) w.push_back(word);
        if (w.empty()) continue;
        auto known = std::find_if(usage.begin(), usage.end(), [&](const auto& u) { return u.first == w[0]; });
        if (known == usage.end()) { std::cout << "error: unknown command '" << w[0] << "'\n"; continue; }
        if (w.size() != static_cast<std::size_t>(std::count(known->second.begin(), known->second.end(), ' ') + 1))
        {
            std::cout << "error: usage: " << known->second << '\n';
            continue;
        }

        // The places named in the command (all but the minutes) must exist, except for `road`.
        std::vector<int> ids;
        if (w[0] == "close" || w[0] == "route" || w[0] == "reach" || w[0] == "far")
        {
            std::size_t names = (w[0] == "close" || w[0] == "route") ? 2 : 1;
            bool ok = true;
            for (std::size_t i = 1; i <= names && ok; ++i)
            {
                auto id = map.find(w[i]);
                if (!id) { std::cout << "error: unknown place '" << w[i] << "'\n"; ok = false; }
                else ids.push_back(*id);
            }
            if (!ok) continue;
        }

        const std::string& cmd = w[0];
        if (cmd == "road")
        {
            auto m = wholeNumber(w[3], 1, 100000);
            if (!m) { std::cout << "error: minutes must be a whole number from 1 to 100000\n"; continue; }
            if (w[1] == w[2]) { std::cout << "error: a road must join two different places\n"; continue; }
            bool added = map.setRoad(map.place(w[1]), map.place(w[2]), *m);
            std::cout << (added ? "added" : "updated") << " road " << w[1] << '-' << w[2] << " (" << *m << " min)\n";
        }
        else if (cmd == "close")
        {
            if (map.closeRoad(ids[0], ids[1])) std::cout << "closed road " << w[1] << '-' << w[2] << '\n';
            else std::cout << "error: no road between " << w[1] << " and " << w[2] << '\n';
        }
        else if (cmd == "route")
        {
            std::vector<int> parent;
            auto best = map.fastest(ids[0], parent);
            if (!best[ids[1]]) { std::cout << "no route from " << w[1] << " to " << w[2] << '\n'; continue; }
            std::vector<int> path;
            for (int v = ids[1]; v != -1; v = parent[v]) path.push_back(v);
            std::reverse(path.begin(), path.end());
            for (std::size_t i = 0; i < path.size(); ++i) std::cout << (i ? " -> " : "") << map.name(path[i]);
            std::cout << " (" << best[ids[1]]->minutes << " min, " << plural(best[ids[1]]->roads, "road", "roads") << ")\n";
        }
        else if (cmd == "reach")
        {
            auto limit = wholeNumber(w[2], 0, 100000000);
            if (!limit) { std::cout << "error: minutes must be a whole number from 0 to 100000000\n"; continue; }
            std::vector<int> parent;
            auto best = map.fastest(ids[0], parent);
            std::vector<std::pair<long long, std::string>> within;
            for (int v = 0; v < map.count(); ++v)
                if (best[v] && best[v]->minutes <= *limit) within.push_back({ best[v]->minutes, map.name(v) });
            std::sort(within.begin(), within.end());
            std::cout << "reach " << w[1] << ' ' << w[2] << ':';
            for (std::size_t i = 0; i < within.size(); ++i) std::cout << (i ? ", " : " ") << within[i].second << ' ' << within[i].first;
            std::cout << '\n';
        }
        else if (cmd == "far")
        {
            std::vector<int> parent;
            auto best = map.fastest(ids[0], parent);
            std::optional<std::pair<long long, std::string>> far;
            for (int v = 0; v < map.count(); ++v)
            {
                if (v == ids[0] || !best[v]) continue;
                std::pair<long long, std::string> candidate{ best[v]->minutes, map.name(v) };
                if (!far || candidate.first > far->first || (candidate.first == far->first && candidate.second < far->second)) far = candidate;
            }
            if (!far) std::cout << "nothing is reachable from " << w[1] << '\n';
            else std::cout << "farthest from " << w[1] << ": " << far->second << " (" << far->first << " min)\n";
        }
        else if (cmd == "network")
        {
            if (map.count() == 0) { std::cout << "network: empty\n"; continue; }
            auto [total, roads, parts] = map.network();
            std::cout << "network: " << total << " min over " << plural(roads, "road", "roads") << ", " << plural(parts, "part", "parts") << '\n';
        }
        else
        {
            if (map.count() == 0) { std::cout << "no places\n"; continue; }
            std::vector<std::string> names = map.names();
            std::sort(names.begin(), names.end());
            std::cout << plural(static_cast<long long>(names.size()), "place", "places") << ':';
            for (std::size_t i = 0; i < names.size(); ++i) std::cout << (i ? ", " : " ") << names[i];
            std::cout << '\n';
        }
    }
}
